// RBACService provides role and permission management to plugins.
//
// Requires the "manage_rbac" plugin permission: the plugin must declare it in
// PluginInfo.required_permissions and an operator must have granted it at
// install time. Without the grant every method here answers with
// success = false and an explanatory error — the module stays importable so a
// plugin can degrade gracefully instead of failing to load.
//
// Permission checks belong in the gameap-authz module, which is open to all
// plugins.
//
// Every method reports failures through the response `error` field and never
// returns an error to the host: a host-side error traps the guest call.
//
// go:plugin type=host module=gameap-rbac
type RBACService interface {
	// SetUserRoles replaces the user's role set. Every name must already exist.
	SetUserRoles(context.Context, *SetUserRolesRequest) (*Result, error)
	// AllowUserAbilitiesForEntity grants the user the listed abilities scoped
	// to one entity.
	AllowUserAbilitiesForEntity(context.Context, *UserAbilitiesRequest) (*Result, error)
	// RevokeOrForbidUserAbilitiesForEntity removes the user's direct grants
	// and, when the abilities are still reachable through a role, records an
	// explicit denial.
	RevokeOrForbidUserAbilitiesForEntity(context.Context, *UserAbilitiesRequest) (*Result, error)
	GetRoles(context.Context, *GetRolesRequest) (*GetRolesResponse, error)
	// SaveRole creates a role when id is 0, updates it otherwise. The stored
	// role, including its assigned id, comes back in the response.
	SaveRole(context.Context, *SaveRoleRequest) (*SaveRoleResponse, error)
	// DeleteRole removes the role along with its assignments and its own
	// permissions. Deleting a role that does not exist is not an error.
	DeleteRole(context.Context, *DeleteRoleRequest) (*Result, error)
	// GetPermissions returns the permission rows attached directly to the
	// entity — for a role, the abilities that role grants.
	GetPermissions(context.Context, *EntityRequest) (*GetPermissionsResponse, error)
	GetRolesForEntity(context.Context, *EntityRequest) (*GetRolesForEntityResponse, error)
	// AssignRolesForEntity adds role assignments; it does not replace existing
	// ones. Pair it with ClearRolesForEntity to replace.
	AssignRolesForEntity(context.Context, *AssignRolesRequest) (*Result, error)
	ClearRolesForEntity(context.Context, *EntityRequest) (*Result, error)
	Allow(context.Context, *AbilitiesRequest) (*Result, error)
	Forbid(context.Context, *AbilitiesRequest) (*Result, error)
	Revoke(context.Context, *AbilitiesRequest) (*Result, error)
}
